827→// ReadLatestSessionContent is a convenience method that reads the latest session's content.
828→// This is equivalent to ReadSessionContent(ctx, checkpointID, len(summary.Sessions)-1).
829→func (s *GitStore) ReadLatestSessionContent(ctx context.Context, checkpointID id.CheckpointID) (*SessionContent, error) {
830→	summary, err := s.ReadCommitted(ctx, checkpointID)
831→	if err != nil {
832→		return nil, err
833→	}
834→	if summary == nil {
835→		return nil, ErrCheckpointNotFound
836→	}
837→	if len(summary.Sessions) == 0 {
838→		return nil, fmt.Errorf("checkpoint has no sessions: %s", checkpointID)
839→	}
840→
841→	latestIndex := len(summary.Sessions) - 1
842→	return s.ReadSessionContent(ctx, checkpointID, latestIndex)
843→}
