845→// ReadSessionContentByID reads a session's content by its session ID.
846→// This is useful when you have the session ID but don't know its index within the checkpoint.
847→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
848→// Returns an error if no session with the given ID exists in the checkpoint.
849→func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
850→	summary, err := s.ReadCommitted(ctx, checkpointID)
851→	if err != nil {
852→		return nil, err
853→	}
854→	if summary == nil {
855→		return nil, ErrCheckpointNotFound
856→	}
857→
858→	// Iterate through sessions to find the one with matching session ID
859→	for i := range len(summary.Sessions) {
860→		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
861→		if readErr != nil {
862→			continue
863→		}
864→		if content != nil && content.Metadata.SessionID == sessionID {
865→			return content, nil
866→		}
867→	}
868→
869→	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
870→}
