 29→
 30→	cmd := &cobra.Command{
 31→		Use:   "resume <branch>",
 32→		Short: "Switch to a branch and resume its session",
 33→		Long: `Switch to a local branch and resume the agent session from its last commit.
 34→
 35→This command:
 36→1. Checks out the specified branch
 37→2. Finds the session ID from commits unique to this branch (not on main)
 38→3. Restores the session log if it doesn't exist locally
 39→4. Shows the command to resume the session
 40→
 41→If the branch doesn't exist locally but exists on origin, you'll be prompted
 42→to fetch it.
 43→
 44→If newer commits without checkpoints exist on the branch (e.g., after merging main
 45→or cherry-picking from elsewhere), this operation will reset your Git status to the
 46→most recent commit with a checkpoint.  You'll be prompted to confirm resuming in this case.`,
 47→		Args: cobra.ExactArgs(1),
 48→		RunE: func(cmd *cobra.Command, args []string) error {
 49→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 50→				return nil
 51→			}
 52→			return runResume(cmd.Context(), args[0], force)
 53→		},
 54→	}
 55→
 56→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Resume from older checkpoint without confirmation")
