221→// getMetadataTree returns the metadata branch tree, trying a treeless fetch
222→// first to ensure local data is up-to-date, then falling back to local,
223→// then full fetch, then remote tree directly.
224→func getMetadataTree(ctx context.Context, repo *git.Repository) (*object.Tree, error) {
225→	// Always try treeless fetch first to ensure local branch is up-to-date
226→	if fetchErr := FetchMetadataTreeOnly(ctx); fetchErr == nil {
227→		metadataTree, err := strategy.GetMetadataBranchTree(repo)
228→		if err == nil {
229→			return metadataTree, nil
230→		}
231→	}
232→
233→	// Try local (may have been set by a prior fetch or push)
234→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
235→	if err == nil {
236→		return metadataTree, nil
237→	}
238→
239→	// Fallback: full fetch from remote
240→	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
241→		metadataTree, err = strategy.GetMetadataBranchTree(repo)
242→		if err == nil {
243→			return metadataTree, nil
244→		}
245→	}
246→
247→	// Try remote tree directly
248→	remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
249→	if remoteErr != nil {
250→		return nil, fmt.Errorf("metadata branch not available: %w", remoteErr)
251→	}
252→	return remoteTree, nil
253→}
254→
255→// ensureTranscriptBlobs checks which transcript blobs for a checkpoint are
256→// present in the local object store (via go-git) and fetches any missing
257→// ones from the remote (via git CLI).
258→// This enables the treeless-fetch optimization: tree objects are fetched first,
259→// then only the specific full.jsonl blobs needed for resume are downloaded.
260→func ensureTranscriptBlobs(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
261→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
262→	if err != nil {
263→		// If we can't get the tree, blobs can't be checked — caller will handle the error
264→		return nil //nolint:nilerr // Tree unavailable means no sparse fetch possible
265→	}
266→
267→	refs, err := checkpoint.CollectTranscriptBlobHashes(metadataTree, checkpointID)
268→	if err != nil {
269→		// Tree navigation failed — not fatal, ReadSessionContent will fail with a clear error
270→		return nil //nolint:nilerr // Best-effort blob prefetch
271→	}
272→
273→	resolver := checkpoint.NewBlobResolver(repo.Storer)
274→	var missing []plumbing.Hash
275→	for _, ref := range refs {
276→		if !resolver.HasBlob(ref.Hash) {
277→			missing = append(missing, ref.Hash)
278→		}
279→	}
280→	if len(missing) == 0 {
281→		return nil
282→	}
283→
284→	return FetchBlobsByHash(ctx, missing)
285→}
