287→// branchCheckpointsResult contains the result of searching for checkpoints on a branch.
288→type branchCheckpointsResult struct {
289→	checkpointIDs     []id.CheckpointID
290→	commitHash        string
291→	commitMessage     string
292→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
293→	newerCommitCount  int  // count of branch-only commits without checkpoints
294→}
