296→// findBranchCheckpoints finds the most recent commit with an Entire-Checkpoint trailer
297→// among commits that are unique to this branch (not reachable from the default branch).
298→// This handles the case where main has been merged into the feature branch.
299→func findBranchCheckpoints(repo *git.Repository, branchName string) (*branchCheckpointsResult, error) {
300→	result := &branchCheckpointsResult{}
301→
302→	// Get HEAD commit
303→	head, err := repo.Head()
304→	if err != nil {
305→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
306→	}
307→
308→	headCommit, err := repo.CommitObject(head.Hash())
309→	if err != nil {
310→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
311→	}
312→
313→	// First, check if HEAD itself has a checkpoint (most common case)
314→	if cpIDs := trailers.ParseAllCheckpoints(headCommit.Message); len(cpIDs) > 0 {
315→		result.checkpointIDs = cpIDs
316→		result.commitHash = head.Hash().String()
317→		result.commitMessage = headCommit.Message
318→		result.newerCommitsExist = false
319→		return result, nil
320→	}
321→
322→	// HEAD doesn't have a checkpoint - find branch-only commits
323→	// Get the default branch name
324→	defaultBranch := getDefaultBranchFromRemote(repo)
325→	if defaultBranch == "" {
326→		// Fallback: try common names
327→		for _, name := range []string{"main", "master"} {
328→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
329→				defaultBranch = name
330→				break
331→			}
332→		}
333→	}
334→
335→	// If we can't find a default branch, or we're on it, just walk all commits
336→	if defaultBranch == "" || defaultBranch == branchName {
337→		return findCheckpointInHistory(headCommit, nil), nil
338→	}
339→
340→	// Get the default branch reference
341→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
342→	if err != nil {
343→		// Default branch doesn't exist locally, fall back to walking all commits
344→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
345→	}
346→
347→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
348→	if err != nil {
349→		// Can't get default commit, fall back to walking all commits
350→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
351→	}
352→
353→	// Find merge base
354→	mergeBase, err := headCommit.MergeBase(defaultCommit)
355→	if err != nil || len(mergeBase) == 0 {
356→		// No common ancestor, fall back to walking all commits
357→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
358→	}
359→
360→	// Walk from HEAD to merge base, looking for checkpoint
361→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
362→}
363→
364→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
365→// If stopAt is provided, stops when reaching that commit (exclusive).
366→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
367→// It distinguishes between merge commits (bringing in other branches) and regular commits
368→// (actual branch work) to avoid false warnings after merging main.
369→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointsResult {
370→	result := &branchCheckpointsResult{}
371→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
372→	const maxCommits = 100 // Limit search depth
373→	totalChecked := 0
374→
375→	current := start
376→	for current != nil && totalChecked < maxCommits {
377→		// Stop if we've reached the boundary
378→		if stopAt != nil && current.Hash == *stopAt {
379→			break
380→		}
381→
382→		// Check for checkpoint trailer
383→		if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
384→			result.checkpointIDs = cpIDs
385→			result.commitHash = current.Hash.String()
386→			result.commitMessage = current.Message
387→			// Only warn about branch work commits, not merge commits
388→			result.newerCommitsExist = branchWorkCommits > 0
389→			result.newerCommitCount = branchWorkCommits
390→			return result
391→		}
392→
393→		// Only count regular commits (not merge commits) as "branch work"
394→		if current.NumParents() <= 1 {
395→			branchWorkCommits++
396→		}
397→
398→		totalChecked++
399→
400→		// Move to parent (first parent for merge commits - follows the main line)
401→		if current.NumParents() == 0 {
402→			break
403→		}
404→		parent, err := current.Parent(0)
405→		if err != nil {
406→			// Can't get parent, treat as end of history
407→			break
408→		}
409→		current = parent
410→	}
411→
412→	// No checkpoint found
413→	return result
414→}
