438→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
439→// and automatically fetches it if available.
440→func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
441→	// Try to get remote metadata branch tree
442→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
443→	if err != nil {
444→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
445→		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
446→		return nil //nolint:nilerr // Informational message, not a fatal error
447→	}
448→
449→	// Check if the checkpoint exists on the remote
450→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
451→	if err != nil {
452→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
453→		return nil //nolint:nilerr // Informational message, not a fatal error
454→	}
455→
456→	// Metadata exists on remote but not locally - fetch it automatically
457→	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
458→	if err := FetchMetadataBranch(ctx); err != nil {
459→		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
460→		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
461→		return NewSilentError(errors.New("failed to fetch metadata"))
462→	}
463→
464→	// Now resume the session with the fetched metadata
465→	return resumeSession(ctx, metadata, false)
466→}
