468→// resumeSession restores and displays the resume command for a specific session.
469→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
470→// If force is false, prompts for confirmation when local logs have newer timestamps.
471→// The caller must provide the already-resolved checkpoint metadata to avoid redundant lookups
472→// and to support both local and remote metadata trees.
473→func resumeSession(ctx context.Context, metadata *strategy.CheckpointInfo, force bool) error {
474→	checkpointID := metadata.CheckpointID
475→	sessionID := metadata.SessionID
476→
477→	// Resolve agent from checkpoint metadata (same as rewind)
478→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
479→	if err != nil {
480→		return fmt.Errorf("failed to resolve agent: %w", err)
481→	}
482→
483→	// Initialize logging context with agent
484→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
485→
486→	logging.Debug(logCtx, "resume session started",
487→		slog.String("checkpoint_id", checkpointID.String()),
488→		slog.String("session_id", sessionID),
489→	)
490→
491→	// Get worktree root for session directory lookup
492→	repoRoot, err := paths.WorktreeRoot(ctx)
493→	if err != nil {
494→		return fmt.Errorf("failed to get worktree root: %w", err)
495→	}
496→
497→	sessionDir, err := ag.GetSessionDir(repoRoot)
498→	if err != nil {
499→		return fmt.Errorf("failed to determine session directory: %w", err)
500→	}
501→
502→	// Create directory if it doesn't exist
503→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
504→		return fmt.Errorf("failed to create session directory: %w", err)
505→	}
506→
507→	// Get strategy and restore sessions using full checkpoint data
508→	strat := GetStrategy(ctx)
509→
510→	// Ensure transcript blobs are available locally before RestoreLogsOnly reads them.
511→	// After a treeless fetch, tree objects are present but full.jsonl blobs may not be.
512→	// This fetches only the specific blobs needed for this checkpoint.
513→	repo, repoErr := openRepository(ctx)
514→	if repoErr == nil {
515→		if blobErr := ensureTranscriptBlobs(ctx, repo, checkpointID); blobErr != nil {
516→			logging.Warn(logCtx, "failed to ensure transcript blobs, restore may fail",
517→				slog.String("error", blobErr.Error()),
518→			)
519→		}
520→	}
521→
522→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
523→	// Create a logs-only rewind point with Agent populated (same as rewind)
524→	point := strategy.RewindPoint{
525→		IsLogsOnly:   true,
526→		CheckpointID: checkpointID,
527→		Agent:        metadata.Agent,
528→	}
529→
530→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
531→	if restoreErr != nil || len(sessions) == 0 {
532→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
533→		return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
534→	}
535→
536→	logging.Debug(logCtx, "resume session completed",
537→		slog.String("checkpoint_id", checkpointID.String()),
538→		slog.Int("session_count", len(sessions)),
539→	)
540→
541→	return displayRestoredSessions(sessions)
542→}
