544→// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
545→func displayRestoredSessions(sessions []strategy.RestoredSession) error {
546→	sort.SliceStable(sessions, func(i, j int) bool {
547→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
548→	})
549→
550→	if len(sessions) > 1 {
551→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
552→	} else if len(sessions) == 1 {
553→		fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
554→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
555→	}
556→
557→	for i, sess := range sessions {
558→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
559→		if err != nil {
560→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
561→		}
562→		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
563→
564→		isLast := i == len(sessions)-1
565→		switch {
566→		case len(sessions) > 1 && isLast && sess.Prompt != "":
567→			fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
568→		case len(sessions) > 1 && isLast:
569→			fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
570→		case sess.Prompt != "":
571→			fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
572→		default:
573→			fmt.Fprintf(os.Stderr, "  %s\n", cmd)
574→		}
575→	}
576→
577→	return nil
578→}
