580→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
581→// Always overwrites existing session logs to ensure consistency with checkpoint state.
582→// If force is false, prompts for confirmation when local log has newer timestamps.
583→func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
584→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
585→	if err != nil {
586→		return fmt.Errorf("failed to resolve transcript path: %w", err)
587→	}
588→
589→	if checkpointID.IsEmpty() {
590→		logging.Debug(ctx, "resume session: empty checkpoint ID",
591→			slog.String("checkpoint_id", checkpointID.String()),
592→		)
593→		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
594→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
595→		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
596→		return nil
597→	}
598→
599→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
600→	if err != nil {
601→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
602→			logging.Debug(ctx, "resume session completed (no metadata)",
603→				slog.String("checkpoint_id", checkpointID.String()),
604→				slog.String("session_id", sessionID),
605→			)
606→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
607→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
608→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
609→			return nil
610→		}
611→		logging.Error(ctx, "resume session failed",
612→			slog.String("checkpoint_id", checkpointID.String()),
613→			slog.String("session_id", sessionID),
614→			slog.String("error", err.Error()),
615→		)
616→		return fmt.Errorf("failed to get session log: %w", err)
617→	}
618→
619→	// Check if local file has newer timestamps than checkpoint
620→	if !force {
621→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
622→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
623→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
624→
625→		if status == strategy.StatusLocalNewer {
626→			sessions := []strategy.SessionRestoreInfo{{
627→				SessionID:      sessionID,
628→				Status:         status,
629→				LocalTime:      localTime,
630→				CheckpointTime: checkpointTime,
631→			}}
632→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
633→			if promptErr != nil {
634→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
635→			}
636→			if !shouldOverwrite {
637→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
638→				return nil
639→			}
640→		}
641→	}
642→
643→	// Ensure parent directory exists
644→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
645→		return fmt.Errorf("failed to create session directory: %w", err)
646→	}
647→
648→	agentSession := &agent.AgentSession{
649→		SessionID:  sessionID,
650→		AgentName:  ag.Name(),
651→		RepoPath:   repoRoot,
652→		SessionRef: sessionLogPath,
653→		NativeData: logContent,
654→	}
655→
656→	// Write the session using the agent's WriteSession method
657→	if err := ag.WriteSession(ctx, agentSession); err != nil {
658→		logging.Error(ctx, "resume session failed during write",
659→			slog.String("checkpoint_id", checkpointID.String()),
660→			slog.String("session_id", sessionID),
661→			slog.String("error", err.Error()),
662→		)
663→		return fmt.Errorf("failed to write session: %w", err)
664→	}
665→
666→	logging.Debug(ctx, "resume session completed",
667→		slog.String("checkpoint_id", checkpointID.String()),
668→		slog.String("session_id", sessionID),
669→	)
670→
671→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
672→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
673→	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
674→	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
675→
676→	return nil
677→}
