616→	// Get checkpoint store
617→	store, err := s.getCheckpointStore()
618→	if err != nil {
619→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
620→	}
621→
622→	// Read checkpoint summary to get session count
623→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
