466→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
467→	metadataPath := checkpointPath + "/metadata.json"
468→	file, err := tree.File(metadataPath)
469→	if err != nil {
470→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
471→	}
472→
473→	reader, err := file.Reader()
474→	if err != nil {
475→		return nil, fmt.Errorf("failed to read metadata: %w", err)
476→	}
477→	defer reader.Close()
478→
479→	// Try to parse as CheckpointSummary first (new format) using lite struct
480→	var summary checkpointSummaryLite
481→	if err := json.NewDecoder(reader).Decode(&summary); err == nil {
482→		// If we have sessions array, this is the new format
483→		if len(summary.Sessions) > 0 {
484→			info := &CheckpointInfo{
485→				CheckpointID:     summary.CheckpointID,
486→				CheckpointsCount: summary.CheckpointsCount,
487→				FilesTouched:     summary.FilesTouched,
488→				SessionCount:     len(summary.Sessions),
489→			}
490→
491→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
492→			var sessionIDs []string
493→			for i, sessionPaths := range summary.Sessions {
494→				if sessionPaths.Metadata == "" {
495→					continue
496→				}
497→				// SessionFilePaths contains absolute paths with leading "/"
498→				// Strip the leading "/" for tree.File() which expects paths without leading slash
499→				sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
500→				sessionMeta, sErr := decodeSessionMetadataLite(tree, sessionMetadataPath)
501→				if sErr != nil {
502→					continue
503→				}
504→				sessionIDs = append(sessionIDs, sessionMeta.SessionID)
505→				// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
506→				if i == 0 {
507→					info.Agent = sessionMeta.Agent
508→					info.SessionID = sessionMeta.SessionID
509→					info.CreatedAt = sessionMeta.CreatedAt
510→					info.IsTask = sessionMeta.IsTask
511→					info.ToolUseID = sessionMeta.ToolUseID
512→				}
513→			}
514→			info.SessionIDs = sessionIDs
515→
516→			return info, nil
517→		}
518→	}
519→
520→	// Fall back to parsing as CheckpointInfo (old format or direct info).
521→	// Re-read the file since the decoder consumed the reader.
522→	fallbackReader, err := file.Reader()
523→	if err != nil {
524→		return nil, fmt.Errorf("failed to re-read metadata: %w", err)
525→	}
526→	defer fallbackReader.Close()
527→
528→	var metadata CheckpointInfo
529→	if err := json.NewDecoder(fallbackReader).Decode(&metadata); err != nil {
530→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
531→	}
532→
533→	return &metadata, nil
534→}
