1531→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
1532→// The agentType is used for reassembling chunks in the correct format.
1533→func readTranscriptFromTree(ctx context.Context, tree *object.Tree, agentType types.AgentType) ([]byte, error) {
1534→	// Collect all transcript-related files
1535→	var chunkFiles []string
1536→	var hasBaseFile bool
1537→
1538→	for _, entry := range tree.Entries {
1539→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
1540→			hasBaseFile = true
1541→		}
1542→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
1543→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
1544→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
1545→			if idx > 0 {
1546→				chunkFiles = append(chunkFiles, entry.Name)
1547→			}
1548→		}
1549→	}
1550→
1551→	// If we have chunk files, read and reassemble them
1552→	if len(chunkFiles) > 0 {
1553→		// Sort chunk files by index
1554→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
1555→
1556→		// Check if base file should be included as chunk 0.
1557→		// NOTE: This assumes the chunking convention where the unsuffixed file
1558→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
1559→		if hasBaseFile {
1560→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
1561→		}
1562→
1563→		var chunks [][]byte
1564→		for _, chunkFile := range chunkFiles {
1565→			file, err := tree.File(chunkFile)
1566→			if err != nil {
1567→				logging.Warn(ctx, "failed to read transcript chunk file from tree",
1568→					slog.String("chunk_file", chunkFile),
1569→					slog.String("error", err.Error()),
1570→				)
1571→				continue
1572→			}
1573→			content, err := file.Contents()
1574→			if err != nil {
1575→				logging.Warn(ctx, "failed to read transcript chunk contents",
1576→					slog.String("chunk_file", chunkFile),
1577→					slog.String("error", err.Error()),
1578→				)
1579→				continue
1580→			}
1581→			chunks = append(chunks, []byte(content))
1582→		}
1583→
1584→		if len(chunks) > 0 {
1585→			result, err := agent.ReassembleTranscript(chunks, agentType)
1586→			if err != nil {
1587→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
1588→			}
1589→			return result, nil
1590→		}
1591→	}
1592→
1593→	// Fall back to reading base file (non-chunked or backwards compatibility)
1594→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
1595→		if content, err := file.Contents(); err == nil {
1596→			return []byte(content), nil
1597→		}
1598→	}
1599→
1600→	// Try legacy filename
1601→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
1602→		if content, err := file.Contents(); err == nil {
1603→			return []byte(content), nil
1604→		}
1605→	}
1606→
1607→	return nil, nil
1608→}
