// CollectCheckpointBlobHashes walks the metadata branch tree for a checkpoint
// and returns blob hashes for ALL files across all sessions.
// Only reads tree objects — works after a treeless fetch where blobs have not
// been downloaded. This is used to pre-fetch all blobs needed before reading
// checkpoint metadata and session content.
func CollectCheckpointBlobHashes(tree *object.Tree, checkpointID id.CheckpointID) ([]plumbing.Hash, error) {
	checkpointTree, err := tree.Tree(checkpointID.Path())
	if err != nil {
		return nil, fmt.Errorf("checkpoint tree %s: %w", checkpointID.Path(), err)
	}

	var hashes []plumbing.Hash
	iterErr := checkpointTree.Files().ForEach(func(f *object.File) error {
		hashes = append(hashes, f.Hash)
		return nil
	})
	if iterErr != nil {
		return nil, fmt.Errorf("walking checkpoint tree: %w", iterErr)
	}
	return hashes, nil
}

