// ensureCheckpointBlobs checks which blobs for a checkpoint subtree are
// present in the local object store (via go-git) and fetches any missing
// ones from the remote (via git CLI).
// This enables the treeless-fetch optimization: tree objects are fetched first,
// then only the specific blobs needed for resume are downloaded.
// The metadataTree parameter should be the already-fetched metadata branch tree.
func ensureCheckpointBlobs(ctx context.Context, repo *git.Repository, metadataTree *object.Tree, checkpointID id.CheckpointID) error {
	hashes, err := checkpoint.CollectCheckpointBlobHashes(metadataTree, checkpointID)
	if err != nil {
		// Tree navigation failed — not fatal, callers will handle read errors
		return nil //nolint:nilerr // Best-effort blob prefetch
	}

	resolver := checkpoint.NewBlobResolver(repo.Storer)
	var missing []plumbing.Hash
	for _, h := range hashes {
		if !resolver.HasBlob(h) {
			missing = append(missing, h)
		}
	}
	if len(missing) == 0 {
		return nil
	}

	return FetchBlobsByHash(ctx, missing)
}

