package checkpoint

import (
	"context"
	"sync"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/storer"
)

// BlobFetchFunc fetches missing blob objects by hash from a remote.
type BlobFetchFunc func(ctx context.Context, hashes []plumbing.Hash) error

// FetchingTree wraps a git tree to automatically fetch missing blobs on demand.
// After a treeless fetch (--filter=blob:none), tree objects are available locally
// but blob objects are not. On the first File() call, this wrapper walks the
// entire subtree, collects all missing blob hashes, and batch-fetches them in
// a single network round-trip. Subsequent File() calls return immediately.
type FetchingTree struct {
	inner    *object.Tree
	ctx      context.Context
	resolver *BlobResolver
	fetch    BlobFetchFunc
	once     *sync.Once // shared across parent/child trees
}

// NewFetchingTree wraps a git tree with on-demand blob fetching.
// The storer is used to check if blobs exist locally, and fetch is called
// to download any that are missing. If fetch is nil, File() behaves
// identically to the underlying tree.
func NewFetchingTree(tree *object.Tree, ctx context.Context, s storer.EncodedObjectStorer, fetch BlobFetchFunc) *FetchingTree {
	return &FetchingTree{
		inner:    tree,
		ctx:      ctx,
		resolver: NewBlobResolver(s),
		fetch:    fetch,
		once:     &sync.Once{},
	}
}

// ensureBlobs walks the entire tree recursively and batch-fetches all
// missing blobs in a single call. Only tree objects are read during the
// walk; blobs are identified by hash from tree entries.
func (t *FetchingTree) ensureBlobs() {
	if t.fetch == nil {
		return
	}
	t.once.Do(func() {
		var missing []plumbing.Hash
		_ = t.inner.Files().ForEach(func(f *object.File) error {
			if !t.resolver.HasBlob(f.Hash) {
				missing = append(missing, f.Hash)
			}
			return nil
		})
		if len(missing) > 0 {
			// Best-effort: if fetch fails, File() will surface the underlying error
			_ = t.fetch(t.ctx, missing)
		}
	})
}

// File returns the file at the given path. On the first call, all missing
// blobs in this tree (and subtrees) are batch-fetched from the remote.
func (t *FetchingTree) File(path string) (*object.File, error) {
	t.ensureBlobs()
	return t.inner.File(path)
}

// Tree returns the subtree at the given path, wrapped with the same fetching
// behavior. The child shares the parent's prefetch state — if the parent
// already fetched blobs (which includes subtree blobs), the child won't
// re-fetch.
func (t *FetchingTree) Tree(path string) (*FetchingTree, error) {
	subtree, err := t.inner.Tree(path)
	if err != nil {
		return nil, err
	}
	return &FetchingTree{
		inner:    subtree,
		ctx:      t.ctx,
		resolver: t.resolver,
		fetch:    t.fetch,
		once:     t.once, // share — parent fetch covers subtree blobs
	}, nil
}

// RawEntries returns the direct tree entries (no blob reads needed).
func (t *FetchingTree) RawEntries() []object.TreeEntry {
	return t.inner.Entries
}

// Unwrap returns the underlying *object.Tree.
func (t *FetchingTree) Unwrap() *object.Tree {
	return t.inner
}

// Files returns a recursive file iterator from the underlying tree.
// This only walks tree objects and does not read blobs.
func (t *FetchingTree) Files() *object.FileIter {
	return t.inner.Files()
}

// FileReader provides read access to files within a git tree.
// Both *object.Tree and *FetchingTree implement this interface.
type FileReader interface {
	File(path string) (*object.File, error)
}

