func (t *FetchingTree) ensureBlobs() {
	if t.fetch == nil {
		return
	}
	t.once.Do(func() {
		var missing []plumbing.Hash
		_ = t.inner.Files().ForEach(func(f *object.File) error { //nolint:errcheck // ForEach callback never returns error
			if !t.resolver.HasBlob(f.Hash) {
				missing = append(missing, f.Hash)
			}
			return nil
		})
		if len(missing) > 0 {
			// Best-effort: if fetch fails, File() will surface the underlying error.
			_ = t.fetch(t.ctx, missing) //nolint:errcheck // caller handles missing blobs
		}
	})
}

