func (t *FetchingTree) ensureBlobs() {
	if t.fetch == nil {
		return
	}
	t.once.Do(func() {
		var total int
		var missing []plumbing.Hash
		walkErr := t.inner.Files().ForEach(func(f *object.File) error {
			total++
			if !t.resolver.HasBlob(f.Hash) {
				missing = append(missing, f.Hash)
			}
			return nil
		})
		if walkErr != nil {
			logging.Debug(t.ctx, "FetchingTree: tree walk failed",
				slog.String("error", walkErr.Error()),
			)
		}
		logging.Debug(t.ctx, "FetchingTree: blob check complete",
			slog.Int("total_files", total),
			slog.Int("missing_blobs", len(missing)),
		)
		if len(missing) > 0 {
			// Best-effort: if fetch fails, File() will surface the underlying error.
			if fetchErr := t.fetch(t.ctx, missing); fetchErr != nil {
				logging.Warn(t.ctx, "FetchingTree: blob fetch failed",
					slog.Int("missing_count", len(missing)),
					slog.String("error", fetchErr.Error()),
				)
			}
		}
	})
}

// File returns the file at the given path. On the first call, all missing
// blobs in this tree (and subtrees) are batch-fetched from the remote.
func (t *FetchingTree) File(path string) (*object.File, error) {
	t.ensureBlobs()
	return t.inner.File(path) //nolint:wrapcheck // pass-through wrapper
}

