func (t *FetchingTree) ensureBlobs() {
	if t.fetch == nil {
		logging.Debug(t.ctx, "FetchingTree.ensureBlobs: no fetch func, skipping")
		return
	}
	t.once.Do(func() {
		var total int
		var missing []plumbing.Hash
		var fileNames []string
		walkErr := t.inner.Files().ForEach(func(f *object.File) error {
			total++
			has := t.resolver.HasBlob(f.Hash)
			if !has {
				missing = append(missing, f.Hash)
			}
			logging.Debug(t.ctx, "FetchingTree.ensureBlobs: file entry",
				slog.String("name", f.Name),
				slog.String("hash", f.Hash.String()[:12]),
				slog.Bool("local", has),
			)
			fileNames = append(fileNames, f.Name)
			return nil
		})
		if walkErr != nil {
			logging.Warn(t.ctx, "FetchingTree.ensureBlobs: tree walk failed",
				slog.String("tree_hash", t.inner.Hash.String()),
				slog.String("error", walkErr.Error()),
			)
		}
		logging.Debug(t.ctx, "FetchingTree.ensureBlobs: walk complete",
			slog.String("tree_hash", t.inner.Hash.String()),
			slog.Int("total_files", total),
			slog.Int("missing_blobs", len(missing)),
			slog.Any("files", fileNames),
		)
		if len(missing) > 0 {
			var hashStrs []string
			for _, h := range missing {
				hashStrs = append(hashStrs, h.String()[:12])
			}
			logging.Debug(t.ctx, "FetchingTree.ensureBlobs: fetching missing blobs",
				slog.Any("hashes", hashStrs),
			)
			if fetchErr := t.fetch(t.ctx, missing); fetchErr != nil {
				logging.Warn(t.ctx, "FetchingTree.ensureBlobs: blob fetch failed",
					slog.Int("missing_count", len(missing)),
					slog.String("error", fetchErr.Error()),
				)
			} else {
				// Verify blobs are now available
				var stillMissing int
				for _, h := range missing {
					if !t.resolver.HasBlob(h) {
						stillMissing++
						logging.Warn(t.ctx, "FetchingTree.ensureBlobs: blob still missing after fetch",
							slog.String("hash", h.String()[:12]),
						)
					}
				}
				if stillMissing > 0 {
					logging.Warn(t.ctx, "FetchingTree.ensureBlobs: some blobs still missing after fetch",
						slog.Int("still_missing", stillMissing),
						slog.Int("fetched", len(missing)-stillMissing),
					)
				} else {
					logging.Debug(t.ctx, "FetchingTree.ensureBlobs: all blobs fetched successfully",
						slog.Int("count", len(missing)),
					)
				}
			}
		}
	})
}

// File returns the file at the given path. On the first call, all missing
// blobs in this tree (and subtrees) are batch-fetched from the remote.
func (t *FetchingTree) File(path string) (*object.File, error) {
	t.ensureBlobs()
	file, err := t.inner.File(path)
	if err != nil {
		logging.Debug(t.ctx, "FetchingTree.File: lookup failed",
			slog.String("path", path),
			slog.String("tree_hash", t.inner.Hash.String()),
			slog.String("error", err.Error()),
		)
	}
	return file, err //nolint:wrapcheck // pass-through wrapper
}
